/// <summary>
/// PaffH 13.12.24
/// set printJobSettings
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ProdParmRelease, NDXSetupButtonProdIdent), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed','Parameter "e"')]
public static void NDXSetupButtonProdIdent_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun thisFormRun = sender.formRun();
    FormDataSource ProdParmRelease_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(ProdParmRelease, ProdParmRelease));
    ProdParmRelease prodParmRelease = ProdParmRelease_DS.cursor();

    SRSPrintDestinationSettings printJobSettings = new SRSPrintDestinationSettings(prodParmRelease.NDXSetupPrintProdProdIdent);
    SrsReportRunUtil::showSettingsDialog(printJobSettings);
    prodParmRelease.NDXSetupPrintProdProdIdent = printJobSettings.pack();
}

/// <summary>
/// PaffH 13.12.24
/// enable/disable Button printJobSettings
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ProdParmRelease, ProdParmRelease_NDXPrintProdProdIdent), FormControlEventType::Modified)
    ,SuppressBPWarning('BPParameterNotUsed','Parameter "e"')]
public static void ProdParmRelease_NDXPrintProdProdIdent_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun thisFormRun = sender.formRun();
    FormDataSource ProdParmRelease_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(ProdParmRelease, ProdParmRelease));
    ProdParmRelease prodParmRelease = ProdParmRelease_DS.cursor();

    if (prodParmRelease.NDXPrintProdProdIdent == NoYes::Yes)
    {
        if (!NDXProdIdentProcedureTable::findInventTable(prodParmRelease.prodTable().inventTable().RecId))
        {
            warning(strfmt("@NDX:NDXItemWithPALabelDefinitionNotFound2", prodParmRelease.prodTable().ItemId));
            prodParmRelease.NDXPrintProdProdIdent = NoYes::No;
        }
    }


    thisFormRun.design().controlName(formControlStr(ProdParmRelease, NDXSetupButtonProdIdent)).enabled(prodParmRelease.NDXPrintProdProdIdent == NoYes::Yes);
}
